-- ----------------------------
-- Table structure for beers
-- ----------------------------
DROP TABLE IF EXISTS `beers`;
CREATE TABLE `beers`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `beer` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `brewery` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `brewery_details` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `abv` decimal(5, 2) NOT NULL,
  `tastingnotes` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `raw_json` json NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_beer_brewery`(`beer` ASC, `brewery` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of beers
-- ----------------------------
INSERT INTO `beers` VALUES (1, 'jail ale', 'dartmoor', 'Location: Princetown, Devon; Founded: 1994; Notes: Dartmoor Brewery is the highest brewery in England.', 4.80, '<h3>Style</h3>\n<p>Best Bitter</p>\n<h3>Appearance</h3>\n<p>Deep amber with a creamy head.</p>\n<h3>Aroma</h3>\n<p>Malty, with hints of caramel and earthy hops.</p>\n<h3>Flavour</h3>\n<p>Balanced bitterness with a malty backbone, notes of dried fruit and a subtle hop presence.</p>\n<h3>Mouthfeel</h3>\n<p>Medium-bodied, smooth, and slightly creamy.</p>\n<h3>Finish</h3>\n<p>Dry and lingering bitterness.</p>\n<h3>Food Pairing</h3>\n<p>Roast beef, hearty stews, mature cheddar cheese.</p>', '{\"abv\": 4.8, \"beer\": \"Jail Ale\", \"brewery\": \"Dartmoor\", \"tastingnotes\": \"<h3>Style</h3>\\n<p>Best Bitter</p>\\n<h3>Appearance</h3>\\n<p>Deep amber with a creamy head.</p>\\n<h3>Aroma</h3>\\n<p>Malty, with hints of caramel and earthy hops.</p>\\n<h3>Flavour</h3>\\n<p>Balanced bitterness with a malty backbone, notes of dried fruit and a subtle hop presence.</p>\\n<h3>Mouthfeel</h3>\\n<p>Medium-bodied, smooth, and slightly creamy.</p>\\n<h3>Finish</h3>\\n<p>Dry and lingering bitterness.</p>\\n<h3>Food Pairing</h3>\\n<p>Roast beef, hearty stews, mature cheddar cheese.</p>\", \"brewery details\": \"Location: Princetown, Devon; Founded: 1994; Notes: Dartmoor Brewery is the highest brewery in England.\"}', '2026-02-18 23:03:01', '2026-02-18 23:03:01');
INSERT INTO `beers` VALUES (2, 'proper job', 'st austell brewery', 'Location: St Austell, Cornwall; Founded: 1851; Notes: St Austell Brewery is a regional brewery founded in 1851 by Walter Hicks. It is known for its range of ales and its association with the Cornish region.', 4.50, '<h3>Style</h3><p>India Pale Ale (IPA)</p><h3>Appearance</h3><p>Deep golden colour with a tight white head.</p><h3>Aroma</h3><p>Grapefruit, citrus and tropical fruit hops.</p><h3>Flavour</h3><p>Citrus and resinous hops dominate. A solid malt backbone provides balance.</p><h3>Mouthfeel</h3><p>Medium-bodied with a crisp bitterness.</p><h3>Finish</h3><p>Dry and hoppy finish.</p><h3>Food Pairing</h3><p>Spicy curries, grilled meats, strong cheeses.</p>', '{\"abv\": 4.5, \"beer\": \"Proper Job\", \"brewery\": \"St Austell Brewery\", \"tastingnotes\": \"<h3>Style</h3><p>India Pale Ale (IPA)</p><h3>Appearance</h3><p>Deep golden colour with a tight white head.</p><h3>Aroma</h3><p>Grapefruit, citrus and tropical fruit hops.</p><h3>Flavour</h3><p>Citrus and resinous hops dominate. A solid malt backbone provides balance.</p><h3>Mouthfeel</h3><p>Medium-bodied with a crisp bitterness.</p><h3>Finish</h3><p>Dry and hoppy finish.</p><h3>Food Pairing</h3><p>Spicy curries, grilled meats, strong cheeses.</p>\", \"brewery details\": \"Location: St Austell, Cornwall; Founded: 1851; Notes: St Austell Brewery is a regional brewery founded in 1851 by Walter Hicks. It is known for its range of ales and its association with the Cornish region.\"}', '2026-02-18 23:15:33', '2026-02-18 23:15:33');
INSERT INTO `beers` VALUES (3, 'king\'s knob', 'st. george brewing company', 'Location: Hampton, VA; Founded: 1998; Notes: St. George Brewing Company is a microbrewery that produces traditional handcrafted beers.', 5.50, '<h3>Style</h3>\n<p>Oktoberfest/Märzen</p>\n<h3>Appearance</h3>\n<p>Clear, deep amber color with an off-white head.</p>\n<h3>Aroma</h3>\n<p>Malty aroma with notes of caramel, bread, and a hint of floral hops.</p>\n<h3>Flavour</h3>\n<p>Balanced flavor with a malty sweetness, caramel notes, and a subtle hop bitterness. Clean and crisp.</p>\n<h3>Mouthfeel</h3>\n<p>Medium-bodied with moderate carbonation.</p>\n<h3>Finish</h3>\n<p>Dry and slightly bitter finish.</p>\n<h3>Food Pairing</h3>\n<p>Pairs well with roasted meats, sausages, and German cuisine.</p>', '{\"abv\": 5.5, \"beer\": \"King\'s Knob\", \"brewery\": \"St. George Brewing Company\", \"tastingnotes\": \"<h3>Style</h3>\\n<p>Oktoberfest/Märzen</p>\\n<h3>Appearance</h3>\\n<p>Clear, deep amber color with an off-white head.</p>\\n<h3>Aroma</h3>\\n<p>Malty aroma with notes of caramel, bread, and a hint of floral hops.</p>\\n<h3>Flavour</h3>\\n<p>Balanced flavor with a malty sweetness, caramel notes, and a subtle hop bitterness. Clean and crisp.</p>\\n<h3>Mouthfeel</h3>\\n<p>Medium-bodied with moderate carbonation.</p>\\n<h3>Finish</h3>\\n<p>Dry and slightly bitter finish.</p>\\n<h3>Food Pairing</h3>\\n<p>Pairs well with roasted meats, sausages, and German cuisine.</p>\", \"brewery details\": \"Location: Hampton, VA; Founded: 1998; Notes: St. George Brewing Company is a microbrewery that produces traditional handcrafted beers.\"}', '2026-02-18 23:25:53', '2026-02-18 23:25:53');
INSERT INTO `beers` VALUES (4, 'owd roger', 'hobsons brewery', 'Location: Cleobury Mortimer, Shropshire; Founded: 1993; Notes: Hobsons Brewery is a regional brewery that focuses on traditional brewing methods.', 6.00, '<h3>Style</h3><p>Strong Old Ale</p><h3>Appearance</h3><p>Deep amber with a reddish hue, clear, with a moderate off-white head.</p><h3>Aroma</h3><p>Malty sweetness with notes of caramel, dried fruit (raisins, figs), and a hint of spice. A subtle alcohol aroma is present.</p><h3>Flavour</h3><p>Rich and complex, with flavours of dark fruit, toffee, and a warming spiciness. A balanced bitterness provides a counterpoint to the sweetness.</p><h3>Mouthfeel</h3><p>Full-bodied and smooth, with a gentle carbonation. A slight warmth from the alcohol adds to the experience.</p><h3>Finish</h3><p>Long and satisfying, with lingering notes of dried fruit, malt, and a subtle bitterness.</p><h3>Food Pairing</h3><p>Pairs well with hearty stews, rich cheeses, and desserts like Christmas pudding.</p>', '{\"abv\": 6, \"beer\": \"Owd Roger\", \"brewery\": \"Hobsons Brewery\", \"tastingnotes\": \"<h3>Style</h3><p>Strong Old Ale</p><h3>Appearance</h3><p>Deep amber with a reddish hue, clear, with a moderate off-white head.</p><h3>Aroma</h3><p>Malty sweetness with notes of caramel, dried fruit (raisins, figs), and a hint of spice. A subtle alcohol aroma is present.</p><h3>Flavour</h3><p>Rich and complex, with flavours of dark fruit, toffee, and a warming spiciness. A balanced bitterness provides a counterpoint to the sweetness.</p><h3>Mouthfeel</h3><p>Full-bodied and smooth, with a gentle carbonation. A slight warmth from the alcohol adds to the experience.</p><h3>Finish</h3><p>Long and satisfying, with lingering notes of dried fruit, malt, and a subtle bitterness.</p><h3>Food Pairing</h3><p>Pairs well with hearty stews, rich cheeses, and desserts like Christmas pudding.</p>\", \"brewery details\": \"Location: Cleobury Mortimer, Shropshire; Founded: 1993; Notes: Hobsons Brewery is a regional brewery that focuses on traditional brewing methods.\"}', '2026-02-19 09:04:39', '2026-02-19 09:04:39');
INSERT INTO `beers` VALUES (5, 'summer lightning', 'hogs back brewery', 'Location: Tongham, Surrey; Founded: 1992; Notes: Hogs Back Brewery is a traditional English brewery known for its Surrey-grown hops.', 4.80, '<h3>Style</h3>\n<p>Golden Ale</p>\n<h3>Appearance</h3>\n<p>Pale gold with a white head.</p>\n<h3>Aroma</h3>\n<p>Delicate hop aroma with hints of citrus and floral notes.</p>\n<h3>Flavour</h3>\n<p>Refreshing hop flavour with a balanced bitterness and a subtle sweetness.</p>\n<h3>Mouthfeel</h3>\n<p>Light-bodied and crisp.</p>\n<h3>Finish</h3>\n<p>Clean and dry finish with a lingering hop presence.</p>\n<h3>Food Pairing</h3>\n<p>Pairs well with salads, grilled chicken, and light cheeses.</p>', '{\"abv\": 4.8, \"beer\": \"Summer Lightning\", \"brewery\": \"Hogs Back Brewery\", \"tastingnotes\": \"<h3>Style</h3>\\n<p>Golden Ale</p>\\n<h3>Appearance</h3>\\n<p>Pale gold with a white head.</p>\\n<h3>Aroma</h3>\\n<p>Delicate hop aroma with hints of citrus and floral notes.</p>\\n<h3>Flavour</h3>\\n<p>Refreshing hop flavour with a balanced bitterness and a subtle sweetness.</p>\\n<h3>Mouthfeel</h3>\\n<p>Light-bodied and crisp.</p>\\n<h3>Finish</h3>\\n<p>Clean and dry finish with a lingering hop presence.</p>\\n<h3>Food Pairing</h3>\\n<p>Pairs well with salads, grilled chicken, and light cheeses.</p>\", \"brewery details\": \"Location: Tongham, Surrey; Founded: 1992; Notes: Hogs Back Brewery is a traditional English brewery known for its Surrey-grown hops.\"}', '2026-02-19 09:22:13', '2026-02-19 09:22:13');
INSERT INTO `beers` VALUES (6, 'summer lightning', 'hopback', 'Location: Downton, Wiltshire, England; Founded: 1986; Notes: Hop Back Brewery was one of the pioneers of the modern British brewing scene, known for its distinctive, hoppy beers. It went into administration in 2018 and was acquired by Kirkstall Brewery.', 5.00, '<h3>Style</h3>\n<p>Golden Ale</p>\n<h3>Appearance</h3>\n<p>Pale gold with a white head.</p>\n<h3>Aroma</h3>\n<p>Floral hops, citrus, and a hint of malt.</p>\n<h3>Flavour</h3>\n<p>Hoppy bitterness balanced by a subtle malt sweetness, notes of grapefruit and herbs.</p>\n<h3>Mouthfeel</h3>\n<p>Crisp and refreshing, medium-bodied.</p>\n<h3>Finish</h3>\n<p>Dry and hoppy.</p>\n<h3>Food Pairing</h3>\n<p>Spicy dishes, fish and chips, salads.</p>', '{\"abv\": 5, \"beer\": \"Summer Lightning\", \"brewery\": \"Hopback\", \"tastingnotes\": \"<h3>Style</h3>\\n<p>Golden Ale</p>\\n<h3>Appearance</h3>\\n<p>Pale gold with a white head.</p>\\n<h3>Aroma</h3>\\n<p>Floral hops, citrus, and a hint of malt.</p>\\n<h3>Flavour</h3>\\n<p>Hoppy bitterness balanced by a subtle malt sweetness, notes of grapefruit and herbs.</p>\\n<h3>Mouthfeel</h3>\\n<p>Crisp and refreshing, medium-bodied.</p>\\n<h3>Finish</h3>\\n<p>Dry and hoppy.</p>\\n<h3>Food Pairing</h3>\\n<p>Spicy dishes, fish and chips, salads.</p>\", \"brewery details\": \"Location: Downton, Wiltshire, England; Founded: 1986; Notes: Hop Back Brewery was one of the pioneers of the modern British brewing scene, known for its distinctive, hoppy beers. It went into administration in 2018 and was acquired by Kirkstall Brewery.\"}', '2026-02-19 09:22:40', '2026-02-19 09:22:40');
INSERT INTO `beers` VALUES (7, 'knee-wobbler ipa', 'fearless', 'Location: Estacada, OR; Founded: 2006; Notes: Fearless Brewing Company is a small brewery located in Estacada, Oregon, known for its handcrafted ales and lagers.', 6.80, '<h3>Style</h3>\n<p>American IPA</p>\n<h3>Appearance</h3>\n<p>Deep golden color with a persistent white head.</p>\n<h3>Aroma</h3>\n<p>Citrus and floral hops dominate, with hints of pine and tropical fruit.</p>\n<h3>Flavour</h3>\n<p>Bold hop bitterness balanced by a solid malt backbone. Flavors of grapefruit, mango, and pine are prominent.</p>\n<h3>Mouthfeel</h3>\n<p>Medium-bodied with a crisp and dry finish.</p>\n<h3>Finish</h3>\n<p>Lingering hop bitterness and a slight malt sweetness.</p>\n<h3>Food Pairing</h3>\n<p>Pairs well with spicy dishes, grilled meats, and strong cheeses.</p>', '{\"abv\": 6.8, \"beer\": \"Knee-Wobbler IPA\", \"brewery\": \"Fearless\", \"tastingnotes\": \"<h3>Style</h3>\\n<p>American IPA</p>\\n<h3>Appearance</h3>\\n<p>Deep golden color with a persistent white head.</p>\\n<h3>Aroma</h3>\\n<p>Citrus and floral hops dominate, with hints of pine and tropical fruit.</p>\\n<h3>Flavour</h3>\\n<p>Bold hop bitterness balanced by a solid malt backbone. Flavors of grapefruit, mango, and pine are prominent.</p>\\n<h3>Mouthfeel</h3>\\n<p>Medium-bodied with a crisp and dry finish.</p>\\n<h3>Finish</h3>\\n<p>Lingering hop bitterness and a slight malt sweetness.</p>\\n<h3>Food Pairing</h3>\\n<p>Pairs well with spicy dishes, grilled meats, and strong cheeses.</p>\", \"brewery details\": \"Location: Estacada, OR; Founded: 2006; Notes: Fearless Brewing Company is a small brewery located in Estacada, Oregon, known for its handcrafted ales and lagers.\"}', '2026-02-20 10:38:13', '2026-02-20 10:38:13');
INSERT INTO `beers` VALUES (8, 'plum porter', 'titanic', 'Location: Stoke-on-Trent, England; Founded: 1985; Notes: Titanic Brewery is an independent brewery known for its traditional ales.', 4.50, '<h3>Style</h3>\n<p>Robust Porter</p>\n<h3>Appearance</h3>\n<p>Deep ruby-brown with a tan head.</p>\n<h3>Aroma</h3>\n<p>Rich plum and dark fruit aromas, with hints of chocolate and roasted malt.</p>\n<h3>Flavour</h3>\n<p>Pronounced plum flavour balanced with dark chocolate, coffee notes, and a subtle bitterness.</p>\n<h3>Mouthfeel</h3>\n<p>Smooth and creamy with a medium body.</p>\n<h3>Finish</h3>\n<p>Lingering plum and dark malt notes with a gentle warmth.</p>\n<h3>Food Pairing</h3>\n<p>Pairs well with rich cheeses, chocolate desserts, and roasted meats.</p>', '{\"abv\": 4.5, \"beer\": \"Plum Porter\", \"brewery\": \"Titanic\", \"tastingnotes\": \"<h3>Style</h3>\\n<p>Robust Porter</p>\\n<h3>Appearance</h3>\\n<p>Deep ruby-brown with a tan head.</p>\\n<h3>Aroma</h3>\\n<p>Rich plum and dark fruit aromas, with hints of chocolate and roasted malt.</p>\\n<h3>Flavour</h3>\\n<p>Pronounced plum flavour balanced with dark chocolate, coffee notes, and a subtle bitterness.</p>\\n<h3>Mouthfeel</h3>\\n<p>Smooth and creamy with a medium body.</p>\\n<h3>Finish</h3>\\n<p>Lingering plum and dark malt notes with a gentle warmth.</p>\\n<h3>Food Pairing</h3>\\n<p>Pairs well with rich cheeses, chocolate desserts, and roasted meats.</p>\", \"brewery details\": \"Location: Stoke-on-Trent, England; Founded: 1985; Notes: Titanic Brewery is an independent brewery known for its traditional ales.\"}', '2026-02-21 00:35:45', '2026-02-21 00:35:45');

-- ----------------------------
-- Table structure for user_beers
-- ----------------------------
DROP TABLE IF EXISTS `user_beers`;
CREATE TABLE `user_beers`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` bigint UNSIGNED NOT NULL,
  `beer` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `brewery` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `drank` tinyint(1) NOT NULL DEFAULT 0,
  `user_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `tasting_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `photos_json` json NULL,
  `date_tasted` date NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_user_beer`(`user_id` ASC, `beer` ASC, `brewery` ASC) USING BTREE,
  CONSTRAINT `fk_user_beers_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

